import { cdnAsset } from '@helpers/media/cdn/cdn.helper';
import type { HomeOutputAsset } from '@props/website/home.props';

// Homepage marketing media is served from the Genfeed CDN
// (s3://cdn.genfeed.ai/assets/site/home/**), not committed to the
// website `public/` folder, keeping the binaries out of the repo and letting the
// assets be refreshed without a code deploy. URLs are built from the shared
// cdnAsset() helper so the CDN base is defined in exactly one place.
//
// Everything below is generated by `scripts/generate-home-video.ts` through the
// same Replicate provider the product uses. Each poster is frame 0 of its own
// encoded MP4, which is what makes the still-to-playback handoff seamless —
// regenerate a clip and its poster together, never one without the other.
const home = (file: string) => cdnAsset(`/assets/site/home/${file}`);

/** The four files every generated clip ships as. */
const clip = (directory: string, name: string) => ({
  mp4: home(`${directory}/${name}.mp4`),
  poster: home(`${directory}/${name}-poster.webp`),
  webm: home(`${directory}/${name}.webm`),
});

export const HOME_HERO_VIDEO = {
  ...clip('hero', 'hero-loop'),
  alt: 'Generated creator footage playing behind the Genfeed headline',
} as const;

/**
 * The link-preview video (`og:video`, and the `/x/card` player). Frame 0 is the
 * homepage OG card (`/og/home`), which then crossfades into the hero loop, so
 * the still `og:image` and the video start on the same pixels. 1200x630 H.264,
 * muted, about 1 MB, 11 s. `og:image` remains the fallback where video is ignored.
 *
 * Built by hand from the card PNG and the hero MP4, then uploaded next to the
 * link-preview art as og/home.mp4 (2 s card hold, 1 s crossfade, 10 s of footage):
 *
 *   ffmpeg -loop 1 -framerate 30 -t 2 -i og-home.png -t 10 -i hero-loop.mp4 \
 *     -filter_complex "[0:v]format=yuv420p,scale=1200:630,setsar=1,fps=30[a];\
 *       [1:v]scale=1200:630:force_original_aspect_ratio=increase,crop=1200:630,\
 *       setsar=1,fps=30,format=yuv420p[b];[a][b]xfade=transition=fade:duration=1:offset=1[v]" \
 *     -map "[v]" -an -c:v libx264 -profile:v high -crf 24 -preset slow \
 *     -movflags +faststart og-home.mp4
 */
export const HOME_SOCIAL_VIDEO = {
  height: 630,
  type: 'video/mp4',
  url: cdnAsset('/assets/og/home.mp4'),
  width: 1200,
} as const;

